use bodb02
GO
truncate table sb.CalculationLogs
truncate table MarkedTransaction
truncate table oddsES
truncate table odds14

DECLARE @batchNo INT = 10000DECLARE @todate SMALLDATETIME = DATEADD(MONTH, -3, GETDATE())-- bettrans
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM bettrans WHERE winlostdate < @todate		 if @@rowcount <> @batchNo			break	endEND

-- bettrans14
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM bettrans14 WHERE winlostdate < @todate		 if @@rowcount <> @batchNo			break	endEND

-- bettransM, betparlaydetail
BEGIN	SELECT	refno	into #tmprefno	FROM	dbo.bettrans b 	WHERE	b.matchid = 29	SELECT	bm.transid	into #tmpSubTransId	FROM	dbo.bettransm bm WITH(NOLOCK)		LEFT JOIN #tmprefno r			ON bm.refno = r.refno	WHERE	r.refno IS NULL	 while (1=1)	 begin		 DELETE top (@batchNo) bm		 FROM bettransm bm			inner join #tmpSubTransId t				ON bm.transid = t.transid		 		 if @@rowcount <> @batchNo			break	end	DROP TABLE #tmpSubTransId	SELECT refno	into #tmpDeletedRefnoBetParlayDetail	FROM	betparlaydetail p WITH(NOLOCK)	WHERE	not exists (SELECT refno from #tmprefno t WHERE t.refno = p.refno)	 while (1=1)	 begin		 DELETE top (@batchNo) p		 FROM betparlaydetail p			inner join #tmpDeletedRefnoBetParlayDetail t				ON p.refno = t.refno		 		 if @@rowcount <> @batchNo			break	end	DROP TABLE #tmpDeletedRefnoBetParlayDetail	SELECT refno	into #tmpDeletedRefnoBetParlayResult	FROM	betparlayresult p WITH(NOLOCK)	WHERE	not exists (SELECT refno from #tmprefno t WHERE t.refno = p.refno)	 while (1=1)	 begin		 DELETE top (@batchNo) p		 FROM betparlayresult p			inner join #tmpDeletedRefnoBetParlayResult t				ON p.refno = t.refno		 		 if @@rowcount <> @batchNo			break	end	DROP TABLE #tmpDeletedRefnoBetParlayResult	DROP TABLE #tmprefno	END-- bettrans14
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM bettrans14 WHERE winlostdate < @todate		 if @@rowcount <> @batchNo			break	endEND

-- transfer
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM transfer WHERE winlostdate < @todate		 if @@rowcount <> @batchNo			break	endEND-- bettransRnG14
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM bettransRnG14 WHERE winlostdate < @todate		 if @@rowcount <> @batchNo			break	endEND-- zzzbettrans
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM zzzbettrans WHERE transdate < @todate		 if @@rowcount <> @batchNo			break	endEND-- TicketVoiding_VoidedTransactionBEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM TicketVoiding_VoidedTransaction WHERE CreatedDate < @todate		 if @@rowcount <> @batchNo			break	endEND-- translog14
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM translog14 WHERE winlostdate < @todate		 if @@rowcount <> @batchNo			break	endEND-- translog
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM translog WHERE winlostdate < @todate		 if @@rowcount <> @batchNo			break	endEND-- bettransRnG
BEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM bettransRnG WHERE winlostdate < @todate		 if @@rowcount <> @batchNo			break	endEND-- Dot_Admin_Assignment_TraderBEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM Dot_Admin_Assignment_Trader WHERE UpdatedTime < @todate		 if @@rowcount <> @batchNo			break	endENDBEGIN	-- TicketVoiding_Request	 while (1=1)	 begin		 DELETE top (@batchNo)FROM TicketVoiding_Request WHERE LastModifiedDate < @todate		 if @@rowcount <> @batchNo			break	end		-- TicketVoiding_RequestDetail	select id	into #tmpTicketVoiding_RequestDetail	from TicketVoiding_RequestDetail r	where not exists (select top 1 1 requestid from TicketVoiding_Request t where t.requestid = r.requestid)	 while (1=1)	 begin		 DELETE top (@batchNo) r		 FROM TicketVoiding_RequestDetail r 			inner join #tmpTicketVoiding_RequestDetail t				on r.id = t.id				 if @@rowcount <> @batchNo			break	end	drop table #tmpTicketVoiding_RequestDetail	-- TicketVoiding_RequestDetailTicket_Single	select id	into #tmpTicketVoiding_RequestDetailTicket_Single	from TicketVoiding_RequestDetailTicket_Single r	where not exists (select top 1 1 requestid from TicketVoiding_Request t where t.requestid = r.requestid)	 while (1=1)	 begin		 DELETE top (@batchNo) r		 FROM TicketVoiding_RequestDetailTicket_Single r 			inner join #tmpTicketVoiding_RequestDetailTicket_Single t				on r.id = t.id				 if @@rowcount <> @batchNo			break	end	drop table #tmpTicketVoiding_RequestDetailTicket_SingleEND-- OddsBEGIN	 while (1=1)	 begin		 DELETE top (@batchNo)FROM Odds WHERE changetime < @todate		 if @@rowcount <> @batchNo			break	endEND--bettransm14BEGIN	SELECT	refno	into #tmprefnobettrans14	FROM	dbo.bettrans14 b 	WHERE	b.matchid = 29	SELECT	bm.transid	into #tmpSubTransId14	FROM	dbo.bettransm14 bm WITH(NOLOCK)		LEFT JOIN #tmprefnobettrans14 r			ON bm.refno = r.refno	WHERE	r.refno IS NULL	 while (1=1)	 begin		 DELETE top (@batchNo) bm		 FROM bettransm14 bm			inner join #tmpSubTransId14 t				ON bm.transid = t.transid		 		 if @@rowcount <> @batchNo			break	end	DROP TABLE #tmpSubTransId14	DROP TABLE #tmprefnobettrans14	END